<script setup>
import MButton from '../../../components/mds/MButton.vue'; import MEmptyState from '../../../components/mds/MEmptyState.vue'; import MMobileTopBar from '../../../components/mds/MMobileTopBar.vue'; import MTag from '../../../components/mds/MTag.vue';
defineProps({ dashboard: Object, days: Number, loading: Boolean, safeAreaStyle: Object }); const emit = defineEmits(['back','range','sources']); function formatNsr(value){return `${Number(value)>0?'+':''}${Number(value||0).toFixed(2)}`;}
</script>
<template><section class="mds-mobile-app flex h-[100dvh] min-w-0 flex-col overflow-hidden bg-[var(--mds-bg)]" :style="safeAreaStyle"><MMobileTopBar title="Giám sát truyền thông" @back="emit('back')"><template #actions><MButton variant="link" class="[&]:h-[var(--mds-mobile-touch-target)]" @click="emit('sources')">Nguồn</MButton></template></MMobileTopBar><main class="min-h-0 flex-1 overflow-y-auto pb-[var(--mds-mobile-safe-bottom)]"><div class="mds-mobile-gutter-x space-y-4 py-4"><div class="flex gap-2"><MButton v-for="range in [7,30,90]" :key="range" :variant="days===range?'primary':'neutral'" :loading="loading&&days===range" @click="emit('range',range)">{{ range }} ngày</MButton></div><MEmptyState v-if="!dashboard" title="Chưa có dữ liệu giám sát" description="Chọn khoảng thời gian hoặc kiểm tra quyền truy cập."/><template v-else><section :class="dashboard.crisis ? 'border-[var(--mds-danger)] bg-[var(--mds-danger-bg)]' : 'border-[var(--mds-success)] bg-[var(--mds-success-bg)]'" class="rounded-lg border p-4"><div class="flex items-start justify-between gap-3"><div><strong>{{ dashboard.crisis ? 'Cảnh báo khủng hoảng' : 'Thương hiệu đang ổn định' }}</strong><p class="mt-1 text-[13px]">{{ dashboard.crisis ? `${dashboard.neg24} tin tiêu cực trong 24 giờ.` : 'Chưa có tiêu cực bất thường trong 24 giờ.' }}</p></div><MTag :color="dashboard.crisis?'danger':'success'">{{ dashboard.crisis?'Rủi ro':'An toàn' }}</MTag></div></section><div class="grid grid-cols-2 gap-3"><article v-for="item in [[dashboard.counts.total,'Tổng bài'],[dashboard.counts.brand,'Đề cập MISA'],[dashboard.neg24,'Tiêu cực 24h'],[dashboard.counts.competitor,'Đối thủ']]" :key="item[1]" class="rounded-lg bg-[var(--mds-bg-page)] p-3"><strong class="text-[20px]">{{ item[0] }}</strong><p class="mt-1 text-[12px] text-[var(--mds-text-secondary)]">{{ item[1] }}</p></article></div><section class="rounded-lg bg-[var(--mds-bg-page)] p-4"><h2 class="text-[15px] font-semibold">Sắc thái đề cập</h2><div class="mt-3 flex justify-between text-center text-[13px]"><span>Tích cực<br><strong class="text-[var(--mds-success)]">{{ dashboard.sentiment.positive }}</strong></span><span>Trung tính<br><strong>{{ dashboard.sentiment.neutral }}</strong></span><span>Tiêu cực<br><strong class="text-[var(--mds-danger)]">{{ dashboard.sentiment.negative }}</strong></span></div><p class="mt-3 text-[13px]">NSR: <strong>{{ formatNsr(dashboard.nsr) }}</strong></p></section><section><h2 class="mb-2 text-[15px] font-semibold">Cảnh báo gần đây</h2><MEmptyState v-if="!dashboard.alerts.length" title="Chưa có cảnh báo" description="Máy chủ sẽ bổ sung cảnh báo tại đây."/><div v-else class="divide-y divide-[var(--mds-border-light)] rounded-lg bg-[var(--mds-bg-page)]"><article v-for="alert in dashboard.alerts" :key="alert.id" class="p-3"><div class="flex items-start gap-2"><MTag :color="alert.level==='critical'?'danger':alert.level==='warning'?'warning':'info'">{{ alert.level }}</MTag><div><strong class="text-[13px]">{{ alert.title }}</strong><p class="mt-1 text-[13px] text-[var(--mds-text-secondary)]">{{ alert.detail }}</p></div></div></article></div></section></template></div></main></section></template>
